from backend.application.identity import HumanIdentityService
from backend.application.organization import OrganizationMembershipService, OrganizationService
from backend.application.rbac import OrganizationRbacAuthorizer, RoleBindingService, RoleService
from backend.core.database.database import DatabaseManager
from backend.domain.security import AuthorizationAction, AuthorizationRequest, AuthorizationResource, SecurityPrincipal
from backend.infrastructure.persistence.sqlalchemy_membership_repository import SQLAlchemyOrganizationMembershipRepository
from backend.infrastructure.persistence.sqlalchemy_organization_repository import SQLAlchemyOrganizationRepository
from backend.infrastructure.persistence.sqlalchemy_rbac_repository import SQLAlchemyRoleBindingRepository, SQLAlchemyRoleRepository
from backend.infrastructure.persistence.sqlalchemy_user_repository import SQLAlchemyUserRepository

def test_rbac_records_and_effective_policy_survive_restart(tmp_path):
    db=DatabaseManager();db.config={"type":"sqlite","sqlite_path":str(tmp_path/'rbac.db'),"echo":False};db.create_tables();users=SQLAlchemyUserRepository(db);user=HumanIdentityService(users).create_initial_user("a@example.com","A","correct horse battery staple");orgs=SQLAlchemyOrganizationRepository(db);org=OrganizationService(orgs).create("Acme");memberships=SQLAlchemyOrganizationMembershipRepository(db);membership=OrganizationMembershipService(memberships,orgs,users).create(user.user_id,org.organization_id);roles=SQLAlchemyRoleRepository(db);role=RoleService(roles).create(org.organization_id,"Analyst",["assessment.create"]);bindings=SQLAlchemyRoleBindingRepository(db);binding=RoleBindingService(bindings,roles,memberships).create(org.organization_id,membership.membership_id,role.role_id)
    principal=SecurityPrincipal.human(user.user_id);from backend.application.organization import OrganizationContextResolver;context=OrganizationContextResolver(users,memberships,orgs).resolve(principal,org.organization_id);authorizer=OrganizationRbacAuthorizer(membership_repository=memberships,role_binding_repository=bindings,role_repository=roles,organization_repository=orgs);request=AuthorizationRequest(principal,AuthorizationAction.ASSESSMENT_CREATE,AuthorizationResource("assessment","a"),organization_context=context);assert authorizer.authorize(request).allowed
    db.close();reopened=DatabaseManager();reopened.config=db.config;reopened.initialize_sync_engine();users=SQLAlchemyUserRepository(reopened);memberships=SQLAlchemyOrganizationMembershipRepository(reopened);roles=SQLAlchemyRoleRepository(reopened);bindings=SQLAlchemyRoleBindingRepository(reopened);orgs=SQLAlchemyOrganizationRepository(reopened);context=OrganizationContextResolver(users,memberships,orgs).resolve(principal,org.organization_id);assert OrganizationRbacAuthorizer(membership_repository=memberships,role_binding_repository=bindings,role_repository=roles,organization_repository=orgs).authorize(AuthorizationRequest(principal,AuthorizationAction.ASSESSMENT_CREATE,AuthorizationResource("assessment","a"),organization_context=context)).allowed
    RoleService(roles).revoke(role.role_id,principal=SecurityPrincipal.system());assert not OrganizationRbacAuthorizer(membership_repository=memberships,role_binding_repository=bindings,role_repository=roles,organization_repository=orgs).authorize(request).allowed
    reopened.close()
